const $=s=>document.querySelector(s);
const escapeHtml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stations=['Gare Centre','République','Université','Hôpital','Stade','Zénith'];
const labels=['Périmètre','Sévérité de l’impact','Période','Message voyageurs','Récapitulatif'];
const severities={interrupted:{label:'Service interrompu',badge:'Tronçon non passant',color:'#b41e28',description:'<strong>Le tronçon est non passant :</strong> aucune circulation n’est calculée sur ce tronçon pendant la période d’application.',legend:'Tronçon interrompu'},reduced:{label:'Service réduit',badge:'Offre de transport réduite',color:'#aa6b12',description:'<strong>Le service est réduit :</strong> une partie des circulations est maintenue sur le tronçon pendant la période d’application.',legend:'Service réduit'},delayed:{label:'Retards',badge:'Circulation perturbée',color:'#aa6b12',description:'<strong>Des retards sont signalés :</strong> les arrêts restent desservis sur le tronçon pendant la période d’application.',legend:'Retards signalés'}};
const newImpact=()=>({severity:'interrupted',from:2,to:3,start:'2026-11-02T06:00',end:'2026-11-06T23:00',message:'En raison de travaux, la ligne 12 est interrompue entre Université et Hôpital. Merci de votre compréhension.'});
let state={title:'Travaux sur la ligne 12',cause:'Travaux',impacts:[newImpact()],current:0,step:1},saved=false;
try{const raw=JSON.parse(localStorage.getItem('traffic-report-draft'));if(raw?.impacts?.length&&raw.impacts.every(i=>severities[i.severity]&&Number.isInteger(i.from)&&i.from>=0&&i.to<6&&i.from<i.to)){state=raw;state.current=0;state.step=1;saved=true;}}catch{}
let impact=()=>state.impacts[state.current];
const toast=message=>{const t=$('#toast');t.textContent=message;t.hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.hidden=true,4000);};
function dirty(){saved=false;$('#save-state').textContent='Modifications non enregistrées';$('.draft').innerHTML='<i></i> Brouillon';}
function bind(id,key,numeric=false){$(id).addEventListener('change',e=>{impact()[key]=numeric?Number(e.target.value):e.target.value;dirty();renderDiagram();});}
function render(){
 $('#title').value=state.title;$('#cause').value=state.cause;
 $('#impact-select').innerHTML=state.impacts.map((_,i)=>`<option value="${i}" ${state.current===i?'selected':''}>Impact n° ${i+1}</option>`).join('');$('#impact-count').textContent=`${state.impacts.length} impact${state.impacts.length>1?'s':''}`;
 $('.steps').innerHTML=labels.map((label,i)=>`${i?'<span class="step-arrow">→</span>':''}<button class="step ${i===state.step?'active':i<state.step?'done':''}" data-step="${i}" ${i===state.step?'aria-current="step"':''}><span class="step-number">${i<state.step?'✓':i+1}</span><span class="step-label">${label}</span></button>`).join('');
 document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>go(Number(b.dataset.step)));$('#progress-bar').style.width=`${(state.step+1)*20}%`;
 const i=impact(),opts=selected=>stations.map((s,n)=>`<option value="${n}" ${n===selected?'selected':''}>${s}</option>`).join('');
 const bodies=[`<h2>Périmètre de l’impact</h2><p class="help">Sélectionnez les arrêts délimitant le tronçon de la ligne 12.</p><div class="fields"><label>Arrêt de début<select id="from">${opts(i.from)}</select></label><label>Arrêt de fin<select id="to">${opts(i.to)}</select></label></div>`,
 `<h2>Sévérité de l’impact</h2><p class="help">Précisez les conséquences de la perturbation sur le service.</p><label class="field">Sévérité<select id="severity">${Object.entries(severities).map(([k,v])=>`<option value="${k}" ${i.severity===k?'selected':''}>${v.label}</option>`).join('')}</select></label>`,
 `<h2>Période d’application</h2><p class="help">Définissez la période durant laquelle cet impact s’applique.</p><div class="fields"><label>Début<input id="start" type="datetime-local" value="${escapeHtml(i.start)}" required></label><label>Fin<input id="end" type="datetime-local" value="${escapeHtml(i.end)}" required></label></div>`,
 `<h2>Message voyageurs</h2><p class="help">Rédigez le message associé à cet impact.</p><label class="field">Message<textarea id="message" maxlength="1000">${escapeHtml(i.message)}</textarea></label>`,
 `<h2>Récapitulatif de l’impact</h2><p class="help">Vérifiez les informations avant de valider votre déclaration.</p><div class="review"><strong>Ligne 12 · ${stations[i.from]} → ${stations[i.to]}</strong><br>${severities[i.severity].label} · Du ${escapeHtml(i.start.replace('T',' à '))} au ${escapeHtml(i.end.replace('T',' à '))}<br>${escapeHtml(i.message)}</div>`];
 $('#form-content').innerHTML=bodies[state.step];$('#previous').disabled=state.step===0;$('#next').hidden=state.step===4;$('#step-count').textContent=`Étape ${state.step+1} sur 5`;
 if(state.step===0){bind('#from','from',true);bind('#to','to',true);}if(state.step===1)bind('#severity','severity');if(state.step===2){bind('#start','start');bind('#end','end');}if(state.step===3)bind('#message','message');
 renderDiagram();
}
function valid(i){if(i.from>=i.to)return 'L’arrêt de fin doit se situer après l’arrêt de début.';if(!i.start||!i.end||i.start>=i.end)return 'La fin doit se situer après le début de la période.';if(!i.message.trim())return 'Ajoutez un message pour les voyageurs.';return '';}
function go(n){const i=impact();if(n>state.step&&state.step===0&&i.from>=i.to)return toast('L’arrêt de fin doit se situer après l’arrêt de début.');if(n>state.step&&state.step===2&&(!i.start||!i.end||i.start>=i.end))return toast('La fin doit se situer après le début de la période.');state.step=Math.max(0,Math.min(4,n));render();}
function renderDiagram(){const i=impact(),s=severities[i.severity],interrupted=i.severity==='interrupted';document.documentElement.style.setProperty('--danger',s.color);$('#diagram-badge').textContent='● '+s.badge;$('#consequence-badge').textContent=s.badge;$('#consequence-text').innerHTML=`Vous avez impacté un tronçon avec la sévérité « ${s.label} ». ${s.description}`;$('#legend-impact').innerHTML=`<i style="width:20px;border-top:3px dotted ${s.color}"></i>${s.legend}`;
 const x=n=>70+n*180;
 $('#diagram').setAttribute('aria-label',`Ligne 12, de Gare Centre à Zénith. ${s.label} entre ${stations[i.from]} et ${stations[i.to]}.`);
 $('#diagram').innerHTML=`<svg viewBox="0 0 1040 140" xmlns="http://www.w3.org/2000/svg"><path d="M70 70H970" stroke="#00353e" stroke-width="5"/><path d="M${x(i.from)} 70H${x(i.to)}" stroke="#f5f4f1" stroke-width="7"/><path d="M${x(i.from)} 70H${x(i.to)}" stroke="${s.color}" stroke-width="5" stroke-dasharray="5 7" stroke-linecap="round"/>${stations.map((name,n)=>{const affected=n>=i.from&&n<=i.to;return `<circle cx="${x(n)}" cy="70" r="8" fill="white" stroke="${affected?s.color:'#00353e'}" stroke-width="2.5"/>${affected&&interrupted?`<path d="M${x(n)-4} 66l8 8m-8 0l8-8" stroke="${s.color}" stroke-width="2"/>`:''}<text x="${x(n)}" y="98" text-anchor="middle" fill="${affected?s.color:'#00353e'}" font-family="Arial,sans-serif" font-size="12" font-weight="${affected?600:400}" ${affected&&interrupted?'text-decoration="line-through"':''}>${name}</text>`;}).join('')}${interrupted?`<circle cx="${(x(i.from)+x(i.to))/2}" cy="70" r="12" fill="${s.color}" stroke="white" stroke-width="3"/><path d="M${(x(i.from)+x(i.to))/2-6} 70h12" stroke="white" stroke-width="3"/>`:''}<g transform="translate(145 43)"><rect width="34" height="18" rx="4" fill="#00aecc" stroke="#00353e" stroke-width="2"/><path d="M5 5h5v6H5zm9 0h5v6h-5zm9 0h6v6h-6" fill="white"/><circle cx="8" cy="19" r="3" fill="#00353e"/><circle cx="27" cy="19" r="3" fill="#00353e"/></g></svg>`;
}
$('#previous').onclick=()=>go(state.step-1);$('#next').onclick=()=>go(state.step+1);$('#impact-select').onchange=e=>{state.current=Number(e.target.value);render();};$('#add').onclick=()=>{state.impacts.push(newImpact());state.current=state.impacts.length-1;state.step=0;dirty();render();toast('Un nouvel impact a été ajouté.');};
$('#title').oninput=e=>{state.title=e.target.value;dirty();};$('#cause').onchange=e=>{state.cause=e.target.value;dirty();};
$('#save').onclick=()=>{try{localStorage.setItem('traffic-report-draft',JSON.stringify(state));saved=true;$('#save-state').textContent='Brouillon enregistré sur cet appareil · '+new Date().toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'});toast('Brouillon enregistré sur cet appareil.');}catch{toast('Le stockage local n’est pas disponible.');}};
$('#finish').onclick=()=>{if(!state.title.trim()){toast('Renseignez un intitulé dans les informations générales.');$('.general').open=true;return;}for(let n=0;n<state.impacts.length;n++){const error=valid(state.impacts[n]);if(error){toast(`Impact ${n+1} : ${error}`);state.current=n;state.step=state.impacts[n].from>=state.impacts[n].to?0:!state.impacts[n].message.trim()?3:2;render();return;}}state.step=4;render();$('.draft').textContent='✓ Vérifiée';toast('Déclaration vérifiée dans le prototype. Aucune diffusion effectuée.');};
$('#collapse').onclick=()=>document.body.classList.toggle('compact');$('#records').onclick=()=>{let record=null;try{record=JSON.parse(localStorage.getItem('traffic-report-draft'));}catch{}$('#records-content').innerHTML=record?`<div class="record"><strong>${escapeHtml(record.title)}</strong><br>${record.impacts.length} impact(s) · Brouillon enregistré sur cet appareil</div>`:'<p>Aucun brouillon enregistré sur cet appareil.</p>';$('#records-dialog').showModal();};$('#close-dialog').onclick=()=>$('#records-dialog').close();$('#new').onclick=()=>{$('#records-dialog').close();document.querySelector('h1').scrollIntoView({behavior:'smooth'});};
const icon={list:'<path d="M8 6h12M8 12h12M8 18h12M3 6h1M3 12h1M3 18h1"/>',alert:'<path d="M10 4a2 2 0 0 1 4 0l8 15a2 2 0 0 1-2 3H4a2 2 0 0 1-2-3z"/><path d="M12 9v5m0 3v1"/>'};document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=`<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icon[el.dataset.icon]}</svg>`);
render();if(saved)$('#save-state').textContent='Brouillon restauré depuis cet appareil.';
